body.t-memphis .bg-fx {
  background-image:
    radial-gradient(circle at 8% 20%, transparent 8px, #f6416c 8px 10px, transparent 10px),
    radial-gradient(#00b8a9 2.5px, transparent 3px),
    radial-gradient(#ffd23f 2.5px, transparent 3px),
    linear-gradient(45deg, transparent 46%, #7b61ff 46% 54%, transparent 54%);
  background-size: 260px 260px, 90px 90px, 120px 120px, 200px 200px;
  background-position: 0 0, 30px 60px, 80px 20px, 140px 100px;
  opacity: .5;
}
body.t-memphis .hero h1 { color: #12121a; }
body.t-memphis .hero h1::first-letter { color: #f6416c; }
body.t-memphis .tagline { color: #00b8a9; font-weight: 800; }
body.t-memphis .section-title { color: #12121a; }
body.t-memphis .section-title::after { content: ""; display: inline-block; width: 44px; height: 10px; margin-left: 14px; background: repeating-linear-gradient(-45deg, #ffd23f 0 6px, transparent 6px 11px); }
body.t-memphis .section-tag { background: #ffd23f; color: #12121a; border-color: #12121a; font-weight: 800; }
body.t-memphis .card { border-color: #12121a; }
body.t-memphis .card:nth-child(3n+1) { border-radius: 22px 6px 22px 6px; }
body.t-memphis .card:nth-child(3n+2) { border-radius: 6px 22px 6px 22px; }
body.t-memphis .card.featured { background: #ffe9f0; border-color: #f6416c; border-width: 3px; }
body.t-memphis .card.featured::before { background: #00b8a9; color: #fff; border: 2px solid #12121a; border-radius: 99px 0 0 99px; }
body.t-memphis .card .star { color: #f6416c; font-weight: 800; }
body.t-memphis .btn { border: 2.5px solid #12121a; font-weight: 800; border-radius: 99px; }
body.t-memphis .btn-primary { background: #f6416c; color: #fff; box-shadow: 4px 4px 0 #12121a; }
body.t-memphis .btn-primary:hover { box-shadow: 7px 7px 0 #00b8a9; }
